updateQuality(url: string, quality: string, wordCount?: number): void {
  const norm = normalizeUrl(url);
  if (wordCount !== undefined) {
    this.db.prepare('UPDATE articles SET quality = ?, word_count = ? WHERE url = ?').run(quality, wordCount, norm);
  } else {
    this.db.prepare('UPDATE articles SET quality = ? WHERE url = ?').run(quality, norm);
  }
}

hasTitleOnDate(title: string, site: string, publishedAt: string | null): { dupe: boolean; existingUrl?: string } {
  const hash = titleHash(title, site, publishedAt);
  if (!hash) return { dupe: false };
  const row = this.db.prepare('SELECT url FROM articles WHERE title_hash = ? LIMIT 1').get(hash) as { url: string } | undefined;
  return row ? { dupe: true, existingUrl: row.url } : { dupe: false };
}

