function validateStandaloneFlags(command: string, args: string[], valueFlags: Set<string>, booleanFlags: Set<string>): void {
  for (let i = 0; i < args.length; i++) {
    const arg = args[i]!;
    if (!arg.startsWith('--')) {
      throw new Error(`${command} does not take positional argument ${JSON.stringify(arg)} after its required argument.`);
    }
    if (valueFlags.has(arg)) {
      const value = args[i + 1];
      if (!value || value.startsWith('--')) throw new Error(`${arg} requires a value. ${exampleForFlag(arg)}`);
      i++;
      continue;
    }
    if (booleanFlags.has(arg)) continue;
    throw new Error(`Unknown option for ${command}: ${arg}. Supported options: ${[...valueFlags, ...booleanFlags].sort().join(', ')}.`);
  }
}

